drop policy if exists tournament_matches_public_read on public.tournament_matches;
create policy tournament_matches_relevant_read on public.tournament_matches for select to anon,authenticated using(exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='completed') or player_a=(select auth.uid()) or player_b=(select auth.uid()) or exists(select 1 from public.tournaments t where t.id=tournament_id and t.created_by=(select auth.uid())) or exists(select 1 from public.tournament_players tp where tp.tournament_id=tournament_id and tp.user_id=(select auth.uid()) and tp.dropped_at is null));
